package edu.seu.vcampus.common.course;
import java.io.*; import java.util.*;
/** Creates an offering and its aggregate schedule rows. */
public record CreateOfferingCommand(String termId,String courseId,String teacherUserId,String className,int capacity,String offeringStatus,List<ScheduleInput> schedules) implements Serializable { @Serial private static final long serialVersionUID=1L; public CreateOfferingCommand{Objects.requireNonNull(termId);Objects.requireNonNull(courseId);Objects.requireNonNull(teacherUserId);Objects.requireNonNull(className);Objects.requireNonNull(offeringStatus);schedules=List.copyOf(Objects.requireNonNull(schedules));CourseValidation.text("termId",termId,36);CourseValidation.text("courseId",courseId,36);CourseValidation.text("teacherUserId",teacherUserId,36);CourseValidation.text("className",className,64);if(capacity<1||!Set.of("DRAFT","OPEN","CLOSED","CANCELLED").contains(offeringStatus))throw new IllegalArgumentException("invalid offering");} public record ScheduleInput(String dayOfWeek,int startPeriod,int endPeriod,int startWeek,int endWeek,String classroom) implements Serializable{@Serial private static final long serialVersionUID=1L;public ScheduleInput{Objects.requireNonNull(dayOfWeek);Objects.requireNonNull(classroom);try{java.time.DayOfWeek.valueOf(dayOfWeek.toUpperCase(java.util.Locale.ROOT));}catch(IllegalArgumentException e){throw new IllegalArgumentException("invalid schedule",e);}CourseValidation.text("classroom",classroom,64);if(startPeriod<1||endPeriod<startPeriod||startWeek<1||endWeek<startWeek)throw new IllegalArgumentException("invalid schedule");}} }
